const raw = $input.first().json || {};
// El agente pasa todo como string JSON en el campo 'input'
let parsed = {};
const inputStr = raw.input || raw.card_id ? JSON.stringify(raw) : '{}';
try { parsed = typeof raw.input === 'string' ? JSON.parse(raw.input) : raw; } catch(e) { parsed = raw; }
const card_id = parsed.card_id ?? raw.card_id ?? parsed.cardId;
const parameters = parsed.parameters ?? raw.parameters ?? [];
if (!card_id) throw new Error('card_id no encontrado. Input recibido: ' + JSON.stringify(raw));
const validCards = [55707, 55705, 63163, 55773, 65209, 66727, 66793];
if (!validCards.includes(Number(card_id))) throw new Error('card_id ' + card_id + ' no autorizado. Válidos: ' + validCards.join(', '));
return [{ json: { card_id: Number(card_id), parameters: Array.isArray(parameters) ? parameters : [] } }];

const resp = $input.first().json;
if (resp.error) return [{ json: { result: 'ERROR', error: resp.error, rows: [], count: 0 } }];
const cols = (resp.data?.cols || []).map(c => c.name);
const rows_raw = resp.data?.rows || [];
const rows = rows_raw.map(r => Object.fromEntries(cols.map((c, i) => [c, r[i]])));
return [{ json: { result: 'OK', rows, count: rows.length } }];
